function StoreShared:DealSettings()
    local settingMgr = SettingMgr:GetInstance()
    local setting = settingMgr:GetSetting(AutoIds.IdSetting601, "StoreGeneralVo")
    ---@type StoreGeneralVo[]
    local tableData = setting:GetAll()
    self.SettingStores = {}
    for i = 1, #tableData do
        --if tableData[i].superiorTab >= 0 then
        --    
        --else
        --    printInfo(tableData[i].id)
        --end
        if not isSet(self.SettingStores, tableData[i].id) then
            local t = {}
            t.voData = tableData[i]
            t.children = {}
            self.SettingStores[tableData[i].id] = t
        else
            self.SettingStores[tableData[i].id].voData = tableData[i]
        end

        if tableData[i].tabRank > 1 then
            local parent = tableData[i].superiorTab
            if not isSet(self.SettingStores, parent) then
                local t = {}
                t.children = {}
                self.SettingStores[parent] = t
            end
            table.insert(self.SettingStores[parent].children, tableData[i].id)
        end
    end

    for k, v in pairs(self.SettingStores) do
        --printInfo("setting %d ", k)
        if v.children ~= nil then
            table.sort(v.children, function(a, b)
                if self.SettingStores[a].voData.tabOrder == self.SettingStores[b].voData.tabOrder then
                    return a < b
                end
                return self.SettingStores[a].voData.tabOrder < self.SettingStores[b].voData.tabOrder
            end)
        end
    end
end

