function StoreShared:LoadSpriteAsync(imageComp, path, nativeSize)
    if isNull(imageComp) then
        return
    end

    KTool.SetActive(imageComp.gameObject, false)

    CSGameUtils.GetSpriteByStringUrlByOwner(path, imageComp, function(sprite)
        --printInfo("GameUtils.LoadSprite")
        if KTool.IsNull(imageComp) then
            return
        end
        --printInfo(path)
        if not KTool.IsNull(sprite) then
            --printInfo("GameUtils.SetSprite")
            imageComp.sprite = sprite
            if nativeSize then
                imageComp:SetNativeSize()
            end

            KTool.SetActive(imageComp.gameObject, true)
        end
    end)

end

function StoreShared:LoadTextureAsync(rawImageComp, path, nativeSize)
    if isNull(rawImageComp) then
        return
    end

    KTool.SetActive(rawImageComp.gameObject, false)

    CSGameUtils.GetSpriteByStringUrlByOwner(path, rawImageComp, function(sprite)
        --printInfo("GameUtils.LoadSprite")
        if KTool.IsNull(rawImageComp) then
            return
        end
        --printInfo(path)
        if not KTool.IsNull(sprite) then
            --printInfo("GameUtils.SetSprite")
            rawImageComp.texture = sprite.texture
            if nativeSize then
                rawImageComp:SetNativeSize()
            end

            KTool.SetActive(rawImageComp.gameObject, true)
        end
    end)

end

