end

function StoreShared:StartTimer(comp)
    self._secondCount = 0
    self._comp = comp
    if not self._updateHandler then
        self._updateHandler = Bind(self,self.OnUpdate)
        MonoHelper.AddUpdateListener(self._updateHandler)
    end
end

function StoreShared:StopTimer()
    self._timerCall = nil
    self._secondCount = 0
    MonoHelper.RemoveUpdateListener(self._updateHandler)
    self._updateHandler = nil
end

function StoreShared:ResetTimer()
    self._secondCount = 0
end

function StoreShared:OnUpdate()
    self._secondCount = self._secondCount + CS.UnityEngine.Time.deltaTime
    if self._secondCount >= CountTime then
        --printInfo("tick %d")
        self._secondCount = self._secondCount - CountTime
        if self._comp ~= nil then
            self._comp:DecreaseTime(CountTime)
        end
        if self._timerCall ~= nil then
            self._timerCall:fire()
        end
    end
end

function StoreShared:RegisterTimer(func)
    assert(type(func) == 'function')
    if self._timerCall == nil then
        self._timerCall = EventLib:new()
    end
    self._timerCall:connect(func)
end

function StoreShared:UnRegisterTimer(func)
    assert(type(func) == 'function')
    if self._timerCall == nil then
        return
    end
    self._timerCall:disconnect(func)
end

---@param comp StoreComponent
function StoreShared:StartActivityTimer(comp)
    self._comp = comp
    self._activityTimer =  CDTimerModule:AddCD(1, function(count, id)
        self._comp.PtActivityStore.remainingTimes = math.max(0, count)
    end, comp.PtActivityStore.remainingTimes, false, true)

    self._activityTimer.OnRemove =  function(count, id)
        self._comp.PtActivityStore.remainingTimes = math.max(0, count)
    end
end

function StoreShared:StopActivityTimer()
    if isNull(self._activityTimer) then
        return
    end

    CDTimerModule:RemoveCD(self._activityTimer)
    self._activityTimer = nil
end



function StoreShared:SetHomeGoodsIds()
    local navigatorBar = GetLuaBehaviour(UINavigationBarRoot.Instance.gameObject, StoreConstants.UINavigatorBarPath)
    if not isNull(navigatorBar) then
        if not KTool.IsNull(navigatorBar.Env) then
            self.HomeGoodsIds = navigatorBar.Env.goodsIds
            self.HomeStatus = {}
            self.HomeStatus.RightStatus = navigatorBar.Env.HealthNode.gameObject.activeInHierarchy
            self.HomeStatus.LeftStatus = navigatorBar.Env.TopLeftNav.gameObject.activeInHierarchy
        end
    end
end

function StoreShared:RefreshCurrency(token)
    local navigatorBar = GetLuaBehaviour(UINavigationBarRoot.Instance.gameObject, StoreConstants.UINavigatorBarPath)
    if not isNull(navigatorBar) then
        if not KTool.IsNull(navigatorBar.Env) then
            navigatorBar.Env:SetRightShow(true, token)
        end
    end
end

function StoreShared:ResetCurrency()
    if self.HomeStatus == nil then
        return
    end
    
    local navigatorBar = GetLuaBehaviour(UINavigationBarRoot.Instance.gameObject, StoreConstants.UINavigatorBarPath)
    if not isNull(navigatorBar) then
        if not KTool.IsNull(navigatorBar.Env) then
            navigatorBar.Env:UpdateHealthNodes(self.HomeGoodsIds)
            KTool.SetActive(navigatorBar.Env.HealthNode.gameObject, self.HomeStatus.RightStatus)
            KTool.SetActive(navigatorBar.Env.TopLeftNav.gameObject, self.HomeStatus.LeftStatus)
            --navigatorBar.Env:SetCustomBackHandlerAction(nil)
            self.HomeStatus = nil
        end
    end
end


return StoreShared